import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpireStaleTest {

    // 2026-11-01 12:00 in Warsaw (CET, UTC+1)
    private static final Clock NOW = Clock.fixed(Instant.parse("2026-11-01T11:00:00Z"), ZoneOffset.UTC);

    private final OrderRepository orders = new OrderRepository();
    private final OrderService service = new OrderService(orders, NOW);

    @Test
    void cancelsPlacedOrdersMoreThanThirtyDaysOld() {
        // 2026-10-01 10:00 Warsaw: 31 calendar days before 2026-11-01
        Order old = place("2026-10-01T09:00:00Z", "PLACED");

        assertEquals(1, service.expireStale());
        assertEquals("CANCELLED", old.status());
    }

    @Test
    void keepsOrdersPlacedExactlyThirtyDaysAgo() {
        // 2026-10-02 in Warsaw: exactly 30 calendar days before 2026-11-01
        Order borderline = place("2026-10-02T10:00:00Z", "PLACED");

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", borderline.status());
    }

    @Test
    void usesTheWarsawDateNotUtc() {
        // 2026-10-01 23:30 UTC is 2026-10-02 01:30 in Warsaw: only 30 days old, so kept
        Order lateNight = place("2026-10-01T23:30:00Z", "PLACED");

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", lateNight.status());
    }

    @Test
    void leavesOrdersInOtherStatusesAlone() {
        Order confirmed = place("2026-09-01T10:00:00Z", "CONFIRMED");
        Order cancelled = place("2026-09-01T10:00:00Z", "CANCELLED");

        assertEquals(0, service.expireStale());
        assertEquals("CONFIRMED", confirmed.status());
        assertEquals("CANCELLED", cancelled.status());
    }

    @Test
    void countsOnlyTheOrdersItCancelled() {
        place("2026-09-01T10:00:00Z", "PLACED");
        place("2026-09-15T10:00:00Z", "PLACED");
        place("2026-10-20T10:00:00Z", "PLACED");
        place("2026-09-01T10:00:00Z", "CONFIRMED");

        assertEquals(2, service.expireStale());
        assertEquals(0, service.expireStale());
    }

    private Order place(String placedAt, String status) {
        Order order = new Order(java.util.UUID.randomUUID().toString(), "c-1",
                Money.pln(1000), Instant.parse(placedAt));
        order.changeStatus(status);
        orders.save(order);
        return order;
    }
}
}
